                return new labelErrorжerror(Ꮡ(new labelError(s, "V6"u8)));
            }
        }
        i += sz;
    }
    return default!;
}

internal static readonly @string zwnj = "\u200c"u8;
internal static readonly @string zwj = "\u200d"u8;

[GoType("num:int8")] partial struct joinState;

internal static joinState stateStart => /* iota */ 0;
internal static joinState stateVirama => 1;
internal static joinState stateBefore => 2;
internal static joinState stateBeforeVirama => 3;
internal static joinState stateAfter => 4;
internal static joinState stateFAIL => 5;

// no-op as we can't accept joiners here
internal static slice<array<joinState>> joinStates = GoReflect.WithElemDims(new golib.SparseArray<array<joinState>>{
    [stateStart] = new golib.SparseArray<joinState>{
        [joiningL] = stateBefore,
        [joiningD] = stateBefore,
        [joinZWNJ] = stateFAIL,
        [joinZWJ] = stateFAIL,
        [joinVirama] = stateVirama}.array(8),
    [stateVirama] = new golib.SparseArray<joinState>{
        [joiningL] = stateBefore,
        [joiningD] = stateBefore}.array(8),
    [stateBefore] = new golib.SparseArray<joinState>{
        [joiningL] = stateBefore,
        [joiningD] = stateBefore,
        [joiningT] = stateBefore,
        [joinZWNJ] = stateAfter,
        [joinZWJ] = stateFAIL,
        [joinVirama] = stateBeforeVirama}.array(8),
    [stateBeforeVirama] = new golib.SparseArray<joinState>{
        [joiningL] = stateBefore,
        [joiningD] = stateBefore,
        [joiningT] = stateBefore}.array(8),
    [stateAfter] = new golib.SparseArray<joinState>{
        [joiningL] = stateFAIL,
        [joiningD] = stateBefore,
        [joiningT] = stateAfter,
        [joiningR] = stateStart,
        [joinZWNJ] = stateFAIL,
        [joinZWJ] = stateFAIL,
        [joinVirama] = stateAfter}.array(8),
    [stateFAIL] = new golib.SparseArray<joinState>{
        [0] = stateFAIL,
        [joiningL] = stateFAIL,
        [joiningD] = stateFAIL,
        [joiningT] = stateFAIL,
        [joiningR] = stateFAIL,
        [joinZWNJ] = stateFAIL,
        [joinZWJ] = stateFAIL,
        [joinVirama] = stateFAIL}.array(8)
}.slice(), 8);

// validateLabel validates the criteria from Section 4.1. Item 1, 4, and 6 are
// already implicitly satisfied by the overall implementation.
[GoRecv] internal static error /*err*/ validateLabel(this ref Profile p, @string s) {
    if (s == ""u8) {
        if (p.verifyDNSLength) {
            return new labelErrorжerror(Ꮡ(new labelError(s, "A4"u8)));
        }
        return default!;
    }
    if (p.checkHyphens) {
        if (len(s) > 4 && s[2] == (rune)'-' && s[3] == (rune)'-') {
            return new labelErrorжerror(Ꮡ(new labelError(s, "V2"u8)));
        }
        if (s[0] == (rune)'-' || s[len(s) - 1] == (rune)'-') {
            return new labelErrorжerror(Ꮡ(new labelError(s, "V3"u8)));
        }
    }
    if (!p.checkJoiners) {
        return default!;
    }
    var trie = p.trie; // p.checkJoiners is only set if trie is set.
    // TODO: merge the use of this in the trie.
    var (v, sz) = trie.lookupString(s);
    var x = ((info)v);
    if (x.isModifier()) {
        return new labelErrorжerror(Ꮡ(new labelError(s, "V5"u8)));
    }
    // Quickly return in the absence of zero-width (non) joiners.
    if (strings.Index(s, zwj) == -1 && strings.Index(s, zwnj) == -1) {
        return default!;
    }
    var st = stateStart;
    for (nint i = 0; ᐧ ; ) {
        var jt = x.joinType();
        if (s.slice(i, i + sz) == zwj){
            jt = joinZWJ;
        } else 
        if (s.slice(i, i + sz) == zwnj) {
            jt = joinZWNJ;
        }
        st = joinStates[st][jt];
        if (x.isViramaModifier()) {
            st = joinStates[st][joinVirama];
        }
        {
            i += sz; if (i == len(s)) {
                break;
            }
        }
        (v, sz) = trie.lookupString(s.slice(i));
        x = ((info)v);
    }
    if (st == stateFAIL || st == stateAfter) {
        return new labelErrorжerror(Ꮡ(new labelError(s, "C"u8)));
    }
    return default!;
}

internal static bool ascii(@string s) {
    for (nint i = 0; i < len(s); i++) {
        if (s[i] >= utf8.RuneSelf) {
            return false;
        }
    }
    return true;
}

